-- Batch attendance import reviewed chronologically by Eric.
-- User companions are confirmed participants; other names remain private guests.

create temporary table attendance_import (
  concert_date text not null,
  venue text not null,
  artists jsonb not null,
  guests jsonb not null,
  papa boolean not null,
  saray boolean not null
) on commit drop;

