create temporary table attendance_targets on commit drop as
select c.id concert_id, i.guests, i.papa, i.saray
from attendance_import i
cross join lateral jsonb_array_elements_text(i.artists) artist(name)
join public.concerts c
  on c.concert_date = i.concert_date
 and c.normalized_venue = public.normalize_concert_value(i.venue)
 and c.normalized_artist = public.normalize_concert_value(artist.name);

do $$
declare expected_count integer; matched_count integer;
begin
  select sum(jsonb_array_length(artists)) into expected_count from attendance_import;
  select count(*) into matched_count from attendance_targets;
  if matched_count <> expected_count then
    raise exception 'Attendance import matched % of % concert rows', matched_count, expected_count;
  end if;
end;
$$;

update public.concert_participants cp
set guest_attendees = coalesce((select array_agg(value order by ordinal)
  from jsonb_array_elements_text(t.guests) with ordinality guest(value, ordinal)), '{}')
from attendance_targets t
join public.profiles eric on lower(eric.email) = 'eric.murillo93@gmail.com'
where cp.concert_id = t.concert_id and cp.user_id = eric.id;

-- Make this reviewed batch authoritative for the two registered companions.
delete from public.concert_participants cp
using attendance_targets t, public.profiles p
where cp.concert_id = t.concert_id
  and cp.user_id = p.id
  and lower(p.email) in ('rpsaray@gmail.com', 'murillodma@gmail.com');

insert into public.concert_participants(concert_id, user_id, bought, status, invited_by, guest_attendees, confirmed_at)
select t.concert_id, companion.id, true, 'confirmed', eric.id, '{}', now()
from attendance_targets t
join public.profiles eric on lower(eric.email) = 'eric.murillo93@gmail.com'
join public.profiles companion on
  (t.papa and lower(companion.email) = 'murillodma@gmail.com') or
  (t.saray and lower(companion.email) = 'rpsaray@gmail.com')
on conflict (concert_id, user_id) do update set
  bought = true,
  status = 'confirmed',
  invited_by = excluded.invited_by,
  guest_attendees = '{}',
  confirmed_at = coalesce(public.concert_participants.confirmed_at, excluded.confirmed_at);
